/// <summary>
/// The <c>AVACreateTraverseTransController</c> class is the controller class for <c>Creating contact persons based on GAB</c>
/// </summary>
class AVACreateTraverseTransController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
///     AVA <c>new</c> method.
/// </summary>
protected void new()
{
    super(classStr(AVACreateTraverseTransService), methodStr(AVACreateTraverseTransService, process), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// construct method of class
/// </summary>
/// <param name = "_executionMode">SysOperationExecutionMode, default SysOperationExecutionMode::Synchronous</param>
/// <returns>AVACreateTraverseTransController</returns>
public static AVACreateTraverseTransController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    AVACreateTraverseTransController controller;
    controller = new AVACreateTraverseTransController();
    controller.parmExecutionMode(_executionMode);
    return controller;
}

/// <summary>
/// main method
/// </summary>
/// <param name = "_args">Args</param>
public static void main(Args _args)
{
    ProdTable   prodTable = _args.record();
    AVACreateTraverseTransController controller;
    AVACreateTraverseTransContract   contract;
    controller = AVACreateTraverseTransController::construct();
    contract = controller.getDataContractObject();
    contract.parmProdId(prodTable.ProdId);
    controller.parmArgs(_args);
    controller.startOperation();
}
